export type ParsedLiquidateInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    receiverOwner: TAccountMetas[0];
    market: TAccountMetas[1];
    target: TAccountMetas[2];
    receiver: TAccountMetas[3];
    /** transfer cannot disqualify it; an initialized maker binding always does. */
    receiverBinding: TAccountMetas[4];
    routeState: TAccountMetas[5];
    vault: TAccountMetas[6];
    eventAuthority: TAccountMetas[7];
    program: TAccountMetas[8];
  };
  data: LiquidateInstructionData;
};

export function parseLiquidateInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedLiquidateInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      receiverOwner: getNextAccount(),
      market: getNextAccount(),
      target: getNextAccount(),
      receiver: getNextAccount(),
      receiverBinding: getNextAccount(),
      routeState: getNextAccount(),
      vault: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getLiquidateInstructionDataDecoder().decode(instruction.data),
  };
}
